import client from "prom-client";
import type { Request, Response, NextFunction } from "express";

client.collectDefaultMetrics(); // event loop lag, heap, GC

const httpDuration = new client.Histogram({
  name: "http_request_duration_seconds",
  help: "HTTP request duration",
  labelNames: ["method", "route", "status_class"],
  buckets: [0.05, 0.1, 0.25, 0.5, 1, 2.5, 5],
});

export function metrics(req: Request, res: Response, next: NextFunction) {
  const end = httpDuration.startTimer();
  res.on("finish", () => {
    end({
      method: req.method,
      // route template, NOT req.path: "/orders/:id" not "/orders/9312"
      route: req.route ? req.baseUrl + req.route.path : "unmatched",
      status_class: `${Math.floor(res.statusCode / 100)}xx`,
    });
  });
  next();
}

export async function metricsHandler(_req: Request, res: Response) {
  res.set("Content-Type", client.register.contentType);
  res.end(await client.register.metrics());
}

const requests = new client.Counter({
  name: "http_requests_total",
  help: "HTTP requests",
  labelNames: ["method", "path", "status"],
});

app.use((req, res, next) => {
  res.on("finish", () => {
    requests.inc({ method: req.method, path: req.originalUrl, status: res.statusCode });
  });
  next();
});

import pino from "pino";
import { AsyncLocalStorage } from "node:async_hooks";
import { randomUUID } from "node:crypto";

export const baseLogger = pino({
  level: process.env.LOG_LEVEL ?? "info",
  redact: {
    paths: [
      "req.headers.authorization",
      "req.headers.cookie",
      "password",
      "otp",
      "*.token",
    ],
    censor: "[Redacted]",
  },
});

const als = new AsyncLocalStorage<pino.Logger>();

// Call once per incoming request (e.g. in middleware)
export function withRequest<T>(incomingId: string | undefined, fn: () => T): T {
  const requestId = incomingId ?? randomUUID();
  return als.run(baseLogger.child({ requestId }), fn);
}

// Anywhere in the request, even after many awaits
export const log = () => als.getStore() ?? baseLogger;

