import { NodeSDK } from "@opentelemetry/sdk-node";
import { getNodeAutoInstrumentations } from "@opentelemetry/auto-instrumentations-node";
import { OTLPTraceExporter } from "@opentelemetry/exporter-trace-otlp-http";

const sdk = new NodeSDK({
  serviceName: "checkout-api",
  traceExporter: new OTLPTraceExporter({ url: "http://otel-collector:4318/v1/traces" }),
  instrumentations: [getNodeAutoInstrumentations()],
});
sdk.start();

// A SIGTERM listener replaces Node's default exit, so exit yourself after flushing.
// In a real app, close the HTTP server first, then flush spans.
process.once("SIGTERM", () => {
  sdk.shutdown().finally(() => process.exit(0));
});

// checkout.ts: a business span around auto-instrumented HTTP/DB spans
import { trace, SpanStatusCode } from "@opentelemetry/api";
const tracer = trace.getTracer("checkout");

export function chargeOrder(orderId: string) {
  return tracer.startActiveSpan("charge order", async (span) => {
    span.setAttribute("order.id", orderId); // detail in attributes, not the name
    try {
      return await paymentProvider.charge(orderId);
    } catch (err) {
      span.recordException(err as Error);
      span.setStatus({ code: SpanStatusCode.ERROR });
      throw err;
    } finally {
      span.end();
    }
  });
}

export function checkout(cart: Cart) {
  return tracer.startActiveSpan("checkout", async (span) => {
    if (cart.items.length === 0) {
      return { ok: false, reason: "empty" };
    }
    const res = await payments.charge(cart);
    span.end();
    return res;
  });
}

queue.process(async (job) => {
