const SLO = 0.999;               // 99.9% of requests are good
const WINDOW_HOURS = 30 * 24;     // 720 h rolling window
const ALLOWED = 1 - SLO;          // 0.1% may fail

/** How much of the budget is spent so far. 1 = all gone. */
export function budgetUsed(total: number, failed: number): number {
  return failed / (total * ALLOWED);
}

/** Burn rate: how fast you spend vs. "exactly on budget" (= 1). */
export function burnRate(errorRatio: number): number {
  return errorRatio / ALLOWED;
}

/** Hours until the whole budget is gone at this burn rate. */
export function hoursToExhaust(rate: number): number {
  return WINDOW_HOURS / rate;
}

budgetUsed(10_000_000, 8_000); // ≈ 0.8 → 80% spent
burnRate(0.0144);              // ≈ 14.4 → page
hoursToExhaust(14.4);          // 50 hours

